page-table.pseudocode:
def translate(vaddr, cr3, user_mode, write):
    idx = [(vaddr >> s) & 0x1FF for s in (39, 30, 21, 12)]
    table = cr3  # PML4 테이블 물리 주소
    for i in idx:  # PML4 → PDPT → PD → PT
        entry = read_phys(table + i * 8)
        if not entry.present:
            raise PageFault(vaddr)
        if user_mode and not entry.user:
            raise PageFault(vaddr)  # U/S: 커널 페이지 보호
        if write and not entry.writable:
            raise PageFault(vaddr)  # R/W 위반
        table = entry.frame_addr  # 다음 단계 테이블
    return table + (vaddr & 0xFFF)  # 프레임 + 오프셋

pagerank.pseudocode:
def pagerank(graph, d=0.85, eps=1e-6):
    # graph: {노드: [링크 대상 노드 목록]}
    nodes = list(graph)
    n = len(nodes)
    pr = {v: 1 / n for v in nodes}
    while True:
        new = {v: (1 - d) / n for v in nodes}  # 임의 이동
        for v in nodes:
            out = graph[v]
            if out:
                for w in out:
                    new[w] += d * pr[v] / len(out)
            else:  # 나가는 링크 없음: 전체에 균등 분배
                for w in nodes:
                    new[w] += d * pr[v] / n
        diff = sum(abs(new[v] - pr[v]) for v in nodes)
        pr = new
        if diff < eps:  # 수렴 판정
            return pr

parameter-efficient-fine-tuning.pseudocode:
class LoRALinear:
    def __init__(self, W0, r, alpha):
        self.W0 = W0  # 사전학습 가중치 d×k, 고정
        d, k = shape(W0)
        self.A = randn(r, k) * 0.01  # 학습 대상
        self.B = zeros(d, r)  # 0 초기화: 시작 시 ΔW=0
        self.scale = alpha / r
    def forward(self, x):
        base = self.W0 @ x
        delta = self.B @ (self.A @ x)  # 저차 경로
        return base + self.scale * delta
    def trainable(self):
        return [self.A, self.B]  # r·(d+k)개만 학습
    def merge(self):  # 배포 시 병합, 추가 지연 없음
        return self.W0 + self.scale * (self.B @ self.A)

parity.pseudocode:
def parity(blocks):
    p = 0
    for b in blocks:
        p ^= b  # P = D1 ⊕ D2 ⊕ ... ⊕ Dn
    return p

def rebuild(survivors, p):  # 블록 1개 손실 시
    x = p
    for b in survivors:
        x ^= b
    return x  # 손실 블록 복원값

def small_write(old_d, new_d, old_p):
    # 구 D·구 P 읽기 2회 + 새 D·새 P 쓰기 2회 = 쓰기 페널티
    return old_p ^ old_d ^ new_d  # 새 패리티

path-traversal.pseudocode:
import os

def safe_open(base, user_path):
    # base: 허용 루트 디렉터리(절대경로)
    base = os.path.realpath(base)
    target = os.path.realpath(os.path.join(base, user_path))
    # 정규화 후 허용 루트 하위인지 확인
    root = base + os.sep
    if target != base and not target.startswith(root):
        raise PermissionError('path traversal')
    return open(target, 'rb')

patricia-trie.pseudocode:
def search(root, key):
    node = root
    while not node.is_leaf:
        # 내부 노드는 분기 비트 위치만 저장
        b = bit(key, node.bit_index)
        node = node.child[b]
    # 생략된 비트 검증: 저장 키와 전체 비교
    if node.key == key:
        return node
    return None

payback-period.pseudocode:
def payback_period(investment, cash_flows, rate=None):
    # rate 지정 시 할인회수기간법 (현재가치로 누적)
    cum = 0.0
    for t, cf in enumerate(cash_flows, start=1):
        if rate is not None:
            cf = cf / (1 + rate) ** t  # t년 현금흐름 할인
        if cf > 0 and cum + cf >= investment:
            return t - 1 + (investment - cum) / cf  # 연중 보간
        cum += cf
    return None  # 분석 기간 내 미회수

# 예: 투자 1,000, 유입 300·400·500 → 2 + 300/500 = 2.6년
